API Gateway.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the API Gateway container

Container_Boundary(api_gateway, "API Gateway") {
    Component(Kong_Enterprise_Routing_Module, "Kong Enterprise Routing Module", "Kong Enterprise", "Manages active-active hybrid Kubernetes routing and security plugin extensibility.")
    Component(Authentication_and_Token_Validation_Module, "Authentication and Token Validation Module", "OAuth2/OIDC, Multi-Factor Auth, TLS 1.3", "Validates user tokens and handles secure user access workflows.")
}

Rel(Kong_Enterprise_Routing_Module, Authentication_and_Token_Validation_Module, "Validates user tokens and checks authentication", "OIDC/OAuth2")

@enduml

HL7 FHIR Integration Service.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the HL7 FHIR Integration Service container

Container_Boundary(hl7_fhir_integration_service, "HL7 FHIR Integration Service") {
    Component(FHIR Parser and Transformer, "FHIR Parser and Transformer", "Java, Spring Boot, HAPI FHIR, Apache Camel", "Parses FHIR R4 payloads and transforms data formats for internal and external systems.")
    Component(Integration Event Producer, "Integration Event Producer", "gRPC, Transactional Outbox Pattern", "Streams asynchronous integration events securely to the Apache Kafka message broker.")
}

Rel(FHIR Parser and Transformer, Integration Event Producer, "Sends transformed integration events", "gRPC, Transactional Outbox Pattern")

@enduml
